#pragma once
#include <cstdint>

namespace stym::gemui::fontdata {

// Glyphs: ASCII 0x20-0x7E (index 0-94), then the GEM glyphs U+E001-U+E008 (95-102: up, down, right, left arrows,
// close box, size box, full-screen box, check mark), then two characters of the Atari ST encoding that the prototype
// takes from its fallback font (D-127): musical note ♪ (103) and bullet • (104), then the AZERTY and QWERTZ key
// legends of the keyboard drawing (D-131): ù, ², Ö, Ä, Ü, ß, ´ (105-111), then the accented letters and signs of the
// Atari ST encoding for the translated tooltips (D-185, 112-150).
inline constexpr int kGlyphCount = 151;
// Characters of the fallback font, from index kFallbackFirst: their code points, in order.
inline constexpr int kFallbackFirst = 103;
inline constexpr int kLatinFirst = 112;  // accented letters of the tooltips (D-185): measurements of the GEM font
inline constexpr int kFallbackCount = kGlyphCount - kFallbackFirst;
extern const char32_t kFallbackCodes[kFallbackCount];
inline constexpr int kSizeCount = 9;  // 8 to 16 px
inline constexpr int kQuarters = 4;   // origin of a glyph at a quarter of a pixel (as in Skia)

struct Size {
    int px;      // CSS font size
    int adv64;   // advance in 1/64 px
    int asc64;   // ascent in 1/64 px
    int desc64;  // descent in 1/64 px
    int top;     // first row, relative to the baseline (negative: above)
    int rows;    // rows per glyph
    // Glyphs rasterised with the origin at q/4 of a pixel: kGlyphCount × rows rows of 16 bits, bit 15 = column 0, to
    // be shifted further by shift[q] columns to the right (sets shared by several quarters).
    const uint16_t* bits[kQuarters];
    int shift[kQuarters];
};

extern const Size kSizes[kSizeCount];

// GEM's 8×8 and 6×6 system fonts (src/FontDataSmall.cpp, generated by tools/gemfont/emutos_small.mjs from EmuTOS):
// small texts (D-071). The same 151 characters; one-byte rows, bit 7 = column 0, the last row for the descenders,
// the one before just above the baseline.
inline constexpr int k8x8MaxPx = 12;  // 8×8 font from 8 to 12 px
inline constexpr int k8x8Rows = 8;
inline constexpr int k8x8Advance = 8;
inline constexpr int k8x8Top = -7;  // first row, relative to the baseline
extern const uint8_t k8x8[kGlyphCount][k8x8Rows];
inline constexpr int k6x6Rows = 6;
inline constexpr int k6x6Advance = 6;
inline constexpr int k6x6Top = -5;
extern const uint8_t k6x6[kGlyphCount][k6x6Rows];

}  // namespace stym::gemui::fontdata
